SELECT detector_proc_id, tracking_process_id, request_tracking_id, detected_time, event_occued_status, detect_record_start_id, detect_record_end_id, tracking_start_date, tracking_end_date, tracking_result_value FROM tracking_detector_proc_info WHERE 1=1
AND detector_proc_id = #{detectorProcId}
ORDER BY detector_proc_id DESC
